using System.Security.Claims;
using Microsoft.EntityFrameworkCore;
using PersonalUltra.Infrastructure;
using PersonalUltra.StudentApi.Contracts;
namespace PersonalUltra.StudentApi.Endpoints;
public static class NutritionProgressEndpointExtensions
{
 public static void MapNutritionProgressApi(this WebApplication app){var api=app.MapGroup("/api/v1").RequireAuthorization();api.MapGet("/nutrition",async(PersonalUltraDbContext db,ClaimsPrincipal u,CancellationToken ct)=>{if(!Student(u,out var id))return ApiEndpointExtensions.ApiError("STUDENT_SESSION_REQUIRED","Use uma sessão válida.",403);var p=await db.NutritionPlans.AsNoTracking().Include(x=>x.Trainer).Include(x=>x.Meals).ThenInclude(x=>x.Foods).ThenInclude(x=>x.Alternatives).SingleOrDefaultAsync(x=>x.StudentId==id,ct);return p is null?Results.Text("null","application/json"):Results.Ok(new StudentNutrition(p.Id,p.Name,p.Notes,p.UpdatedAt,p.Trainer.Name,p.Meals.OrderBy(x=>x.Sequence).Select(m=>new StudentMeal(m.Id,m.Name,m.Sequence,m.Notes,m.Foods.OrderBy(f=>f.Sequence).Select(f=>new StudentMealFood(f.Id,f.FoodName,f.Quantity,f.Unit,f.Sequence,f.Alternatives.OrderBy(a=>a.Sequence).Select(a=>new StudentMealFoodAlternative(a.Id,a.FoodName,a.Quantity,a.Unit,a.Sequence,a.Notes)).ToArray())).ToArray())).ToArray(),new StudentNutritionDailyGoals(p.DailyCalories,p.DailyProteinGrams,p.DailyCarbohydratesGrams,p.DailyFatGrams)));});api.MapGet("/progress/weight",async(PersonalUltraDbContext db,ClaimsPrincipal u,CancellationToken ct)=>{if(!Student(u,out var id))return ApiEndpointExtensions.ApiError("STUDENT_SESSION_REQUIRED","Use uma sessão válida.",403);return Results.Ok(await db.WeightEntries.AsNoTracking().Where(x=>x.StudentId==id).OrderBy(x=>x.RecordedAt).Select(x=>new StudentWeight(x.Id,x.WeightKg,x.RecordedAt)).ToListAsync(ct));});api.MapPost("/progress/weight",async(AddWeightRequest r,PersonalUltraDbContext db,ClaimsPrincipal u,TimeProvider clock,CancellationToken ct)=>{if(!Student(u,out var id))return ApiEndpointExtensions.ApiError("STUDENT_SESSION_REQUIRED","Use uma sessão válida.",403);if(r.WeightKg is < 25 or > 400||!ValidDate(r.RecordedAt,clock))return ApiEndpointExtensions.ApiError("VALIDATION_ERROR","Informe um peso e uma data válidos.",400);var e=new PersonalUltra.Domain.WeightEntry{Id=Guid.NewGuid(),StudentId=id,WeightKg=r.WeightKg,RecordedAt=UtcOrNow(r.RecordedAt,clock)};db.WeightEntries.Add(e);await db.SaveChangesAsync(ct);return Results.Ok(new StudentWeight(e.Id,e.WeightKg,e.RecordedAt));});api.MapPut("/progress/weight/{entryId:guid}",async(Guid entryId,UpdateWeightRequest r,PersonalUltraDbContext db,ClaimsPrincipal u,TimeProvider clock,CancellationToken ct)=>{if(!Student(u,out var id))return ApiEndpointExtensions.ApiError("STUDENT_SESSION_REQUIRED","Use uma sessão válida.",403);if(r.WeightKg is < 25 or > 400||!ValidDate(r.RecordedAt,clock))return ApiEndpointExtensions.ApiError("VALIDATION_ERROR","Informe um peso e uma data válidos.",400);var e=await db.WeightEntries.SingleOrDefaultAsync(x=>x.Id==entryId&&x.StudentId==id,ct);if(e is null)return Results.NotFound();e.WeightKg=r.WeightKg;e.RecordedAt=UtcOrNow(r.RecordedAt,clock);await db.SaveChangesAsync(ct);return Results.Ok(new StudentWeight(e.Id,e.WeightKg,e.RecordedAt));});api.MapDelete("/progress/weight/{entryId:guid}",async(Guid entryId,PersonalUltraDbContext db,ClaimsPrincipal u,CancellationToken ct)=>{if(!Student(u,out var id))return ApiEndpointExtensions.ApiError("STUDENT_SESSION_REQUIRED","Use uma sessão válida.",403);var e=await db.WeightEntries.SingleOrDefaultAsync(x=>x.Id==entryId&&x.StudentId==id,ct);if(e is null)return Results.NotFound();db.WeightEntries.Remove(e);await db.SaveChangesAsync(ct);return Results.NoContent();});api.MapGet("/progress/hydration",async(PersonalUltraDbContext db,ClaimsPrincipal u,CancellationToken ct)=>{if(!Student(u,out var id))return ApiEndpointExtensions.ApiError("STUDENT_SESSION_REQUIRED","Use uma sessão válida.",403);return Results.Ok(await db.HydrationEntries.AsNoTracking().Where(x=>x.StudentId==id).OrderBy(x=>x.RecordedAt).Select(x=>new StudentHydration(x.Id,x.AmountMl,x.RecordedAt)).ToListAsync(ct));});api.MapPost("/progress/hydration",async(AddHydrationRequest r,PersonalUltraDbContext db,ClaimsPrincipal u,TimeProvider clock,CancellationToken ct)=>{if(!Student(u,out var id))return ApiEndpointExtensions.ApiError("STUDENT_SESSION_REQUIRED","Use uma sessão válida.",403);if(r.AmountMl is < 1 or > 10000||!ValidDate(r.RecordedAt,clock))return ApiEndpointExtensions.ApiError("VALIDATION_ERROR","Informe uma quantidade e uma data válidos.",400);var e=new PersonalUltra.Domain.HydrationEntry{Id=Guid.NewGuid(),StudentId=id,AmountMl=r.AmountMl,RecordedAt=UtcOrNow(r.RecordedAt,clock)};db.HydrationEntries.Add(e);await db.SaveChangesAsync(ct);return Results.Ok(new StudentHydration(e.Id,e.AmountMl,e.RecordedAt));});api.MapPut("/progress/hydration/{entryId:guid}",async(Guid entryId,UpdateHydrationRequest r,PersonalUltraDbContext db,ClaimsPrincipal u,TimeProvider clock,CancellationToken ct)=>{if(!Student(u,out var id))return ApiEndpointExtensions.ApiError("STUDENT_SESSION_REQUIRED","Use uma sessão válida.",403);if(r.AmountMl is < 1 or > 10000||!ValidDate(r.RecordedAt,clock))return ApiEndpointExtensions.ApiError("VALIDATION_ERROR","Informe uma quantidade e uma data válidos.",400);var e=await db.HydrationEntries.SingleOrDefaultAsync(x=>x.Id==entryId&&x.StudentId==id,ct);if(e is null)return Results.NotFound();e.AmountMl=r.AmountMl;e.RecordedAt=UtcOrNow(r.RecordedAt,clock);await db.SaveChangesAsync(ct);return Results.Ok(new StudentHydration(e.Id,e.AmountMl,e.RecordedAt));});api.MapDelete("/progress/hydration/{entryId:guid}",async(Guid entryId,PersonalUltraDbContext db,ClaimsPrincipal u,CancellationToken ct)=>{if(!Student(u,out var id))return ApiEndpointExtensions.ApiError("STUDENT_SESSION_REQUIRED","Use uma sessão válida.",403);var e=await db.HydrationEntries.SingleOrDefaultAsync(x=>x.Id==entryId&&x.StudentId==id,ct);if(e is null)return Results.NotFound();db.HydrationEntries.Remove(e);await db.SaveChangesAsync(ct);return Results.NoContent();});api.MapGet("/coach/answer",async(string? question,PersonalUltraDbContext db,ClaimsPrincipal u,CancellationToken ct)=>{if(!Student(u,out var id))return ApiEndpointExtensions.ApiError("STUDENT_SESSION_REQUIRED","Use uma sessão válida.",403);var q=(question??"").Trim().ToLowerInvariant();var workout=await db.StudentWorkouts.AsNoTracking().Where(x=>x.StudentId==id&&x.IsActive&&x.Exercises.Any()).OrderBy(x=>x.SuggestedOrder).ThenBy(x=>x.CreatedAt).ThenBy(x=>x.Id).FirstOrDefaultAsync(ct);var nutrition=await db.NutritionPlans.AsNoTracking().SingleOrDefaultAsync(x=>x.StudentId==id,ct);var answer=q.Contains("treino")&&workout is not null?$"O primeiro treino na ordem organizada pelo seu personal é {workout.Name}, com {await db.StudentWorkoutExercises.CountAsync(x=>x.StudentWorkoutId==workout.Id,ct)} exercícios. Você pode escolher outro treino disponível quando preferir.":q.Contains("aliment")&&nutrition is not null?$"Seu plano alimentar atual é {nutrition.Name}. Consulte as refeições cadastradas no app.":"Posso explicar seus treinos disponíveis, sua alimentação e os registros já cadastrados pelo seu personal.";return Results.Ok(new CoachAnswer(answer,["treinos disponíveis","alimentação cadastrada"]));});}
 static DateTimeOffset UtcOrNow(DateTimeOffset? value,TimeProvider clock)=>value?.ToUniversalTime()??clock.GetUtcNow();
 static bool ValidDate(DateTimeOffset? value,TimeProvider clock)=>value is null||value.Value<=clock.GetUtcNow().AddMinutes(5);
 static bool Student(ClaimsPrincipal u,out Guid id)=>Guid.TryParse(u.FindFirstValue(ClaimTypes.NameIdentifier),out id)&&u.FindFirstValue("subject")=="student";
}
